def is_samepatterns(colors, patterns):
    """
    Check whether the colors array follows the same sequence as the patterns array.

    Args:
        colors: A list of color values
        patterns: A list of pattern values

    Returns:
        bool: True if colors follow the same sequence as patterns, False otherwise
    """
    # If lengths are different, they can't follow the same pattern
    if len(colors) != len(patterns):
        return False

    # Create mappings for both arrays
    color_to_pattern = {}
    pattern_to_color = {}

    for color, pattern in zip(colors, patterns):
        # Check if this color has been seen before
        if color in color_to_pattern:
            # If it has, the pattern must match
            if color_to_pattern[color] != pattern:
                return False
        else:
            # This color hasn't been seen, check if this pattern has been assigned to another color
            if pattern in pattern_to_color:
                if pattern_to_color[pattern] != color:
                    return False
            # Assign this color to this pattern
            color_to_pattern[color] = pattern
            pattern_to_color[pattern] = color

    return True
